import {
  AfterViewInit,
  Directive,
  Input,
  TemplateRef,
  ViewContainerRef,
  inject,
  input,
} from '@angular/core';
import { ReplaceableComponentsService } from '@abp/ng.core';

@Directive({ selector: '[abpIfReplaceableTemplateExists]' })
export class IfReplaceableTemplateExistsDirective implements AfterViewInit {
  private view = inject(ViewContainerRef);
  private template = inject<TemplateRef<any>>(TemplateRef);
  private replaceableComponentsService = inject(ReplaceableComponentsService);

  abpIfReplaceableTemplateExists = input<string>('');

  ngAfterViewInit(): void {
    const replaceableComponentInstance = this.replaceableComponentsService.get(
      this.abpIfReplaceableTemplateExists(),
    );
    const isReplaceableComponentInstanceNotExits =
      !replaceableComponentInstance;
    if (isReplaceableComponentInstanceNotExits) {
      return;
    }
    this.view.createEmbeddedView(this.template);
  }
}
